N = 1 << 10
FULL = (1 << N) - 1

def relu_truth(values):
    # For Boolean-valued symbolic channels, ReLU of an integer-valued linear
    # combination is evaluated pointwise over the truth-table positions.
    out = 0
    for i, v in enumerate(values):
        if v > 0:
            out |= 1 << i
    return out

